fn iabs(v: i32) -> i32 {
    if v < 0 { 0 - v } else { v }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, 20 * 16);
        host::display::state_set(2, 20 * 16);
        host::display::state_set(3, 50);
        host::display::state_set(4, 0);
    }
    let mut x: i32 = host::display::state_get(1);
    let mut y: i32 = host::display::state_get(2);
    let mut vx: i32 = host::display::state_get(3);
    let mut vy: i32 = host::display::state_get(4);
    vy = vy + 4;
    x = x + vx;
    y = y + vy;
    if x < 0 { x = 0; vx = 0 - vx; }
    if x > (w - 14) * 16 { x = (w - 14) * 16; vx = 0 - vx; }
    let floor: i32 = (h - 16) * 16;
    if y > floor {
        y = floor;
        vy = (0 - vy) * 7 / 8;
        vx = vx * 7 / 8;
    }
    if y == floor && iabs(vx) < 3 && iabs(vy) < 6 {
        let seed: i32 = host::display::state_get(5) * 1103515245 + 12345;
        host::display::state_set(5, seed);
        let mut kick: i32 = (seed >> 16) % 60;
        if kick < 0 { kick = 0 - kick; }
        vx = kick + 30;
        vy = 0 - 90;
    }
    host::display::state_set(1, x);
    host::display::state_set(2, y);
    host::display::state_set(3, vx);
    host::display::state_set(4, vy);
    host::display::clear(0x000000);
    host::display::fill_rect(0, h - 2, w, 2, 0x306030);
    host::display::fill_rect(x / 16, y / 16, 14, 14, 0xff8800);
    host::display::present();
}
